SYSVAR_CHANS:                  equ 05c4fh   ; Address of channel data
SYSVAR_CURCHL:                 equ 05c51h   ; Address of information used for input and output
SYSVAR_SCR_CT:                 equ 05c8ch   ; Scroll counter
SYSVAR_ATTR_T:                 equ 05c8fh   ; Temporary current colours
SYSVAR_ATTR_P:                 equ 05c8dh   ; Permanent current colours
SYSVAR_COORDS:                 equ 05c7dh   ; Coordinates of last point plotted
SYSVAR_MODE:                   equ 05c41h   ; Specifies K, L, C, E or G cursor
SYSVAR_S_POSNL2:               equ 05c8bh   ; Like S-POSN for lower part of screen 
SYSVAR_DF_SZ:                  equ 05c6bh   ; The number of lines in the lower part of the screen
SYSVAR_BORDCR:                 equ 05c48h   ; Border colour
SYSVAR_SEED:                   equ 05c76h   ; The seed for RND
SYSVAR_FRAMES:                 equ 05c78h   ; Frame counter
SYSVAR_P_FLAG:                 equ 05c91h   ; More flags

; -----------------------------------------------------------------------------
; Tagged term representation
; -----------------------------------------------------------------------------
; Most runtime terms occupy one three-byte cell:
;
;   +0  tag
;   +1  payload low byte
;   +2  payload high byte
;
; Some tags interpret the payload as a value, others as an absolute or relative
; pointer.  Names remain conservative where the exact semantic distinction is
; not yet proved.

TERM_CELL_SIZE:                    equ 003h
FLOAT_VALUE_SIZE:                  equ 006h

; ----------------------------------------------------------------------------
; THE TERM LANGUAGE
; ----------------------------------------------------------------------------
;
; Every Prolog value begins with a tag byte and normally carries a 16-bit
; payload.  A cell is therefore small enough to copy cheaply yet rich enough to
; describe atoms, integers, lists and several kinds of reference.
;
; The reference tags are the subtle part.  A relative reference names a fresh
; variable in a clause environment; an absolute reference names a cell
; directly; REFERENCE_NEXT_CELL points at the second half of a six-byte object
; without publishing an interior heap address to the collector.  The unifier
; follows all three until it reaches an actual value or an unbound variable.
;
; Bit 7 is not another type.  The collector borrows it temporarily as a mark
; bit, then clears it during sweep.  Code which asks what a term *is* must mask
; that bit when collection may have marked the object.
;
; Reference tags: one variable through its lifetime
; -------------------------------------------------
; A variable begins as an unbound three-byte cell:
;
;       address V:   [ UNBOUND | unused word ]
;
; It can later become one of three references:
;
;   ABSOLUTE_REFERENCE  [ 01 | address T ]
;       Follow T directly.  This is the ordinary binding form.
;
;   REFERENCE_NEXT_CELL [ 05 | address of this cell ] [ value cell follows ]
;       Follow the adjacent cell.  The representation is useful when a binding
;       and its copied value are allocated as one six-byte object.
;
;   RELATIVE_REFERENCE [ 0C | byte offset N ]
;       Add N to the current clause-local environment base.  Compiled clauses
;       use this form so the same stored clause can receive fresh variables on
;       every invocation.
;
; Example: binding X to integer 7 normally changes only X:
;
;       before: X = [ 00 | ---- ]
;       value:      [ 04 | 0007 ]
;       after:  X = [ 01 | &value ]
;
; Dereferencing repeatedly follows these forms until it reaches a concrete term
; or an unbound variable.  The complete executable walk appears in module 02 at
; term_dereference_hl.
; ----------------------------------------------------------------------------
; COMPLETE LIFE OF ONE LOGICAL VARIABLE
; ----------------------------------------------------------------------------
;
; The same source variable changes representation as it moves through the
; interpreter.  The following trace is the reference example used by the
; executor and unifier chapters.
;
; Source clause:
;
;       ((P X) (Q X))
;
; Stored clause (read-only):
;
;       head X = [ RELATIVE_REFERENCE | 0000 ]
;       body X = [ RELATIVE_REFERENCE | 0000 ]
;
; `0000` means "the first local cell of this invocation".  On clause entry the
; selector allocates a fresh environment base E and initializes:
;
;       E+0 = [ UNBOUND_VARIABLE | ---- ]
;
; Dereferencing either stored X adds the relative offset to E and reaches the
; same local cell.  If unification binds X to integer 7, the local becomes:
;
;       E+0 = [ ABSOLUTE_REFERENCE | address(integer_7) ]
;
; If X was allocated before the current choice point, the binding also creates
; a six-byte trail node:
;
;       [ target = E+0 ] [ previous = old_trail_head ]
;
; On failure, rollback follows that node and restores only the tag:
;
;       E+0 = [ UNBOUND_VARIABLE | payload ignored ]
;
; A REFERENCE_NEXT_CELL binding follows the same lifetime.  It is used when the
; bound value is the adjacent second cell of a six-byte heap object; rollback
; recovers that adjacent address before clearing its tag.  Thus RELATIVE is the
; compiled-clause form, ABSOLUTE/NEXT_CELL are runtime binding forms, and
; UNBOUND is the state restored by backtracking.
TERM_TAG_UNBOUND_VARIABLE:         equ 000h
TERM_TAG_ABSOLUTE_REFERENCE:       equ 001h
TERM_TAG_LIST:                     equ 003h
TERM_TAG_INTEGER:                  equ 004h
TERM_TAG_REFERENCE_NEXT_CELL:      equ 005h
TERM_TAG_CONSTANT:                 equ 008h
TERM_TAG_FLOAT:                    equ 00ah
TERM_TAG_RELATIVE_REFERENCE:       equ 00ch
TERM_TAG_END:                      equ 010h
TERM_TAG_MODULE:                   equ 007h
TERM_MARK_BIT_INDEX:               equ 007h

; During unification B is a two-bit provenance mask.  A set bit means the
; corresponding operand was reached by following at least one encoded
; reference.  This affects whether a value can be copied directly or must be
; normalized away from its source environment before a variable is bound.
; The word "provenance" below means only how the operand was reached.  A set bit
; says "dereferencing crossed at least one reference cell, so the resolved term
; may belong to a temporary environment".  These are not truth flags, success
; flags, or extra term-type bits.
UNIFY_LEFT_WAS_REFERENCED_BIT:      equ 000h
UNIFY_RIGHT_WAS_REFERENCED_BIT:     equ 001h

; Trail nodes are ordinary two-cell allocations used in a special context.
; The first cell names the variable whose tag was overwritten; the second cell
; is a LIST link to the previous trail head.  The 0x0C tag is reused here as a
; GC-visible marker for a fixed execution-arena address, not as an environment
; offset.  Heap variables use normal absolute or next-cell references.
; Why a trail exists
; ------------------
; Prolog may bind an old variable and later discover that the chosen clause
; fails.  Rewinding heap and frame cursors removes young allocations, but an old
; variable cell remains in place and must be restored explicitly.  The trail is
; a linked undo log of exactly those old cells.
;
; Pseudocode for backtracking is:
;
;       while trail_head != saved_trail_boundary:
;           variable = trail_head.target
;           variable.tag = UNBOUND
;           trail_head = trail_head.previous
;
; Choice points, the age test, and the exact untrail routine are introduced in
; modules 01 and 02.  At this point only the six-byte record layout is needed.
; In the trail discussion an "old" variable means one allocated before the
; current choice point.  Rewinding the allocation frontiers cannot remove such
; a cell, so it needs an explicit undo record.  A "young" variable was allocated
; after the choice point and disappears automatically when the frontier is
; restored.  The numeric age test is worked through in module 02.
TRAIL_NODE_SIZE:                    equ 006h
TRAIL_TARGET_CELL:                  equ 000h
TRAIL_PREVIOUS_CELL:                equ 003h
TRAIL_TARGET_EXECUTION_CELL:        equ TERM_TAG_RELATIVE_REFERENCE
TRAIL_TARGET_HEAP_CELL:             equ TERM_TAG_ABSOLUTE_REFERENCE
TRAIL_TARGET_HEAP_NEXT_CELL:        equ TERM_TAG_REFERENCE_NEXT_CELL

SYSTEM_NAME_TERMINATOR:            equ 0ffh
DISPATCH_REJECT:                   equ 0ffh

; Shared cells in the permanent supervisor term graph.  These aliases are used
; by the reconstructed CL and DELCL definitions without pretending that the
; neighbouring still-unconverted supervisor program is executable code.
; Permanent term-graph anchors
; ----------------------------
; These addresses name cells in the precompiled supervisor program stored later
; in the image.  They are analogous to labels for read-only AST nodes: module 10
; renders the surrounding graphs back into clauses such as EQ, OR, CL, and
; DELCL.  Keeping the aliases here lets earlier executable code refer to those
; immutable terms without forcing the reader to understand their full graph yet.
; Reading advice: do not decode the numeric addresses in the following aliases at
; this point.  Treat them as opaque read-only syntax-tree handles.  Module 10
; reconstructs every permanent graph symbolically and prints its source-level
; clause before showing the tagged cells which prove it.
STATIC_ARGS_V0_V1:                    equ 0847fh ; proper list (V0 V1)
STATIC_ARGS_V1:                       equ 08485h ; proper list (V1)
SUPERVISOR_EQ_VALUE_CELL:              equ 083f5h
SUPERVISOR_OR_VALUE_CELL:              equ 08467h
SUPERVISOR_ALL_VALUE_CELL:             equ 087b6h
STATIC_ARGS_V0:                       equ 088afh ; proper list (V0)

