; One cassette file may be open at a time.  The mutable state byte lies at
; 0x9B96; the surrounding 0x134-byte record also contains an expected block
; identity, a byte cursor, a 256-byte physical transfer area, and the ten-byte
; identity footer stored on tape.  Only payload indexes 0..254 are used: 0xFF
; is reserved as the input-refill cursor, so the physical byte at index 255 is
; padding immediately before the footer.
; Only one cassette file can be open in this Spectrum build.  FILE_CONTROL_TABLE
; therefore names one 0x134-byte control block rather than an array of active
; files.  Module 12 explains its state, 255-byte payload convention, numbered
; block footer, refill path, EOF marker, and final partial-block flush.
FILE_CONTROL_TABLE:                equ 09b96h
FILE_CONTROL_BLOCK_COUNT:          equ 001h
FILE_CONTROL_BLOCK_STRIDE:         equ 0134h
FILE_CONTROL_STATE:                equ 000h
FILE_CONTROL_CURSOR:               equ 002h
FILE_CONTROL_DATA:                 equ 003h
FILE_CONTROL_EXPECTED_IDENTITY:    equ -024h ; eight-byte name + two ASCII digits
FILE_CONTROL_BLOCK_NUMBER:         equ -01ch ; relative to state, identity +8
FILE_CONTROL_TRANSFER_FOOTER:      equ 103h  ; state +3 + 0x100 physical bytes
FILE_CONTROL_FOOTER_BLOCK_NUMBER:  equ 10bh  ; footer +8
FILE_CONTROL_PHYSICAL_DATA_SIZE:   equ 100h
FILE_CONTROL_USABLE_DATA_SIZE:     equ 0ffh  ; indexes 0..0xFE
FILE_CONTROL_TAPE_RECORD_SIZE:     equ 10ah  ; 256 data bytes + 10-byte footer
FILE_CONTROL_NAME_SIZE:            equ 008h
FILE_CONTROL_IDENTITY_SIZE:        equ 00ah
FILE_CONTROL_UNUSED_FLAG:          equ 0fch ; cleared by OPEN/CREATE; exact role unknown

FILE_STATE_FREE:                   equ 000h
FILE_STATE_READING:                equ 001h
FILE_STATE_WRITING:                equ 002h
FILE_CURSOR_REFILL_REQUIRED:       equ 0ffh
FILE_BUFFER_EOF:                   equ 01ah

