DEVICE_OP_READER_INPUT:            equ 003h
DEVICE_OP_PUNCH_OUTPUT:            equ 004h
DEVICE_OP_PRINTER_OUTPUT:          equ 005h
DEVICE_OP_CONSOLE_IO:              equ 006h
DEVICE_OP_INIT_INPUT_IDENTITY:     equ 00fh
DEVICE_OP_READ_TAPE_BLOCK:         equ 014h
DEVICE_OP_WRITE_TAPE_BLOCK:        equ 015h
DEVICE_OP_INIT_OUTPUT_IDENTITY:    equ 016h
DEVICE_OP_SELECT_TRANSFER_BUFFER:  equ 01ah
FILE_TAPE_BLOCK_TYPE:              equ 0fbh

; Primitive-dispatch scratch slots.  Each six-byte slot retains both the
; resolved argument and enough information to bind an unbound output.
; ----------------------------------------------------------------------------
; PRIMITIVE ARGUMENT DISPATCH
; ----------------------------------------------------------------------------
;
; Native predicates do not each contain a hand-written argument parser.  They
; share a compact state machine.  Each five-byte state says where to go for a
; numeric term, a constant, another bound term, or an unbound variable; a zero
; transition means that combination is illegal.
;
; The dispatcher walks the call arguments, dereferences them, stores useful
; addresses in six-byte scratch slots, and advances through these relative
; transitions.  What looked in the original disassembly like tiny nonsensical
; instruction sequences is therefore data: a miniature bytecode describing the
; legal modes of a relation.
;
; ----------------------------------------------------------------------------
; ONE SIX-BYTE PRIMITIVE ARGUMENT SLOT
; ----------------------------------------------------------------------------
;
; The dispatcher uses one heap-object-sized slot for each argument:
;
;       +0  state/tag of the resolved input, or 0xFF when slot is unused
;       +1  original destination low byte
;       +2  original destination high byte
;       +3  resolved value / pending-result tag
;       +4  resolved value / pending-result payload low
;       +5  resolved value / pending-result payload high
;
; For an input, +3..+5 hold the dereferenced value seen by the handler.  For an
; unbound output, +1..+2 remember the variable which must eventually receive a
; value, while the handler writes its proposed result to +3..+5.  Results are
; committed only after the handler returns logical success.  The overlapping
; aliases below deliberately name the same bytes from these different phases.
PRIMITIVE_ARG1_SLOT:              equ 09807h
PRIMITIVE_ARG2_SLOT:              equ 0980dh
PRIMITIVE_ARG3_SLOT:              equ 09813h
PRIMITIVE_ARG4_SLOT:              equ 09819h

PRIMITIVE_ARG1_RESULT_TAG:        equ 09807h
PRIMITIVE_ARG1_RESULT_VALUE:      equ 09808h
PRIMITIVE_ARG1_VALUE:             equ 0980ah
PRIMITIVE_ARG1_TAG:               equ 0980ch
PRIMITIVE_ARG2_RESULT_TAG:        equ 0980dh
PRIMITIVE_ARG2_RESULT_VALUE:      equ 0980eh
PRIMITIVE_ARG2_VALUE:             equ 09810h
PRIMITIVE_ARG2_TAG:               equ 09812h
PRIMITIVE_ARG3_RESULT_TAG:        equ 09813h
PRIMITIVE_ARG3_RESULT_VALUE:      equ 09814h
PRIMITIVE_ARG3_VALUE:             equ 09816h
PRIMITIVE_ARG3_TAG:               equ 09818h
PRIMITIVE_ARG4_RESULT_TAG:        equ 09819h
PRIMITIVE_ARG4_RESULT_VALUE:      equ 0981ah
PRIMITIVE_ARG4_VALUE:             equ 0981ch
PRIMITIVE_ARG4_TAG:               equ 0981eh
PRIMITIVE_ARG5_VALUE:             equ 09822h
PRIMITIVE_ARG6_VALUE:             equ 09828h
ERROR_HANDLER_VALUE_CELL:         equ 09b1ah ; cached dictionary value for "?ERROR?"
CONSOLE_LAST_CHARACTER:            equ 09b69h
TAPE_TRANSFER_BUFFER_PTR:          equ 09b6ah
ACTIVE_FILE_CONTROL_BLOCK:         equ 09b6dh

; Arithmetic work areas.  The dispatcher converts each numeric argument into
; an eleven-byte sign/exponent/decimal-digit buffer before arithmetic.  Two
; larger scratch regions hold intermediate sums, products and quotients.
; The numeric workspaces are declared here only because this is the global memory
; map.  A first-time reader may skip their field details until module 11.  The
; important preview is that packed decimal digits are expanded to one digit per
; byte, with separate sign, exponent, carry and guard positions.
NUMERIC_WORK_A:                   equ 09b1fh
NUMERIC_WORK_A_EXPONENT:          equ NUMERIC_WORK_A+1
NUMERIC_WORK_A_FIRST_DIGIT:       equ NUMERIC_WORK_A+2
NUMERIC_WORK_A_LAST_DIGIT:        equ NUMERIC_WORK_A+10
NUMERIC_WORK_A_END:               equ NUMERIC_WORK_A+18
NUMERIC_WORK_B:                   equ 09b33h
NUMERIC_WORK_B_DIGIT_WINDOW:      equ NUMERIC_WORK_B+8
NUMERIC_ARG1_BUFFER:              equ 09b47h
NUMERIC_ARG2_BUFFER:              equ 09b52h
NUMERIC_ARG3_BUFFER:              equ 09b5dh

; Generic list-walker callback trampoline.  Address 0x9800 contains JP and the
; following word is changed by callers to select the element callback.
LIST_WALK_CALLBACK_JUMP:            equ 09800h
LIST_WALK_CALLBACK_TARGET:          equ 09801h

; Module and dictionary workspace copied from supervisor_workspace_template
; during cold start.  A module descriptor contains three dictionary lists:
;
;   descriptor +0   exported names
;   descriptor +3   LIST -> second six-byte pair
;   second pair +0  imported names
;   second pair +3  local names owned by the module
;
; The root module keeps its second pair directly in this workspace, so its
; import and local dictionaries are also permanent garbage-collector roots.
; Miniature module example
; ------------------------
; Suppose module M exports E, imports I, and privately owns L:
;
;       MODULE_CURRENT_CELL -> constant M
;       M.value             -> MODULE descriptor
;                                +0 exports -> (E)
;                                +3 pair
;                                    +0 imports -> (I)
;                                    +3 locals  -> (L)
;
; A lookup made while M is open searches system names first, then E, then I,
; then L.  Exported and imported dictionary nodes preserve canonical value-cell
; identity; the lists describe visibility, not copies of the constants.
MODULE_CURRENT_CELL:                equ 09a8dh ; CONST(current module object)
MODULE_CURRENT_OBJECT:              equ 09a8eh ; payload of MODULE_CURRENT_CELL
MODULE_CURRENT_DESCRIPTOR:          equ 09a91h ; payload of current module object
MODULE_CURRENT_PROGRAM:                equ MODULE_CURRENT_DESCRIPTOR ; legacy alias
ROOT_MODULE_IMPORT_DICTIONARY:      equ 09a93h
ROOT_MODULE_LOCAL_DICTIONARY:       equ 09a96h
GC_DICTIONARY_ROOT_A:               equ ROOT_MODULE_IMPORT_DICTIONARY ; legacy alias
GC_DICTIONARY_ROOT_B:               equ ROOT_MODULE_LOCAL_DICTIONARY  ; legacy alias
MODULE_ROOT_IMPORT_CELL_PTR:        equ 09a89h ; temporary pointer used by CRMOD/KILL
MODULE_ROOT_LOCAL_CELL_PTR:         equ 09a8bh ; temporary pointer used by CRMOD/KILL
GC_ERROR_HANDLER_ROOT:              equ 09b19h

MODULE_DESCRIPTOR_EXPORTS:          equ 000h
MODULE_DESCRIPTOR_SECOND_PAIR:      equ 003h
MODULE_SECOND_PAIR_IMPORTS:         equ 000h
MODULE_SECOND_PAIR_LOCALS:          equ 003h

; Dictionary names occupy a separately managed pool.  One bitmap bit represents
; one eight-byte pool block.  The first block holds the three-byte value cell,
; up to four name bytes and the 0xFF terminator; each additional block adds eight
; name bytes.  Input names use 0xFE as the temporary terminator.
; ----------------------------------------------------------------------------
; MEMORY GROWS FROM BOTH ENDS
; ----------------------------------------------------------------------------
;
; The fixed workspace is followed by the dictionary-name pool and then by one
; shared arena.  Execution frames and fresh clause variables grow upward.
; Managed term objects grow downward.  Allocation succeeds while the two
; frontiers remain apart; when they approach, the collector marks live objects,
; trims dead objects from the heap edge, and threads interior holes into a free
; list.
;
; Dictionary spellings use a separate bitmap allocator because their addresses
; must remain stable: compiled constants point at canonical dictionary value
; cells, not at copies of their text.
;
DICTIONARY_NAME_POOL_BASE_PTR:       equ 09805h
DICTIONARY_ALLOCATION_BITMAP:       equ 09a99h
DICTIONARY_INPUT_BUFFER:            equ 09ca5h
DICTIONARY_INPUT_GUARD:             equ 09ce4h
DICTIONARY_INPUT_TERMINATOR:        equ 0feh
DICTIONARY_STORED_TERMINATOR:       equ 0ffh
DICTIONARY_DYNAMIC_VALUE_MIN:        equ DICTIONARY_NAME_POOL_START ; first user-name value cell
; With the stock 48K top-of-memory stack, cold start reserves 0x1180 bytes for
; dictionary names (560 eight-byte blocks) and initializes 70 bitmap bytes.
; The calculation is dynamic, so these values document the distributed image
; rather than imposing constants on relocated builds.
DEFAULT_DICTIONARY_POOL_BYTES:          equ 01180h
DEFAULT_DICTIONARY_POOL_BLOCKS:         equ 0230h
DEFAULT_DICTIONARY_BITMAP_BYTES:        equ 046h
DEFAULT_EXEC_ARENA_LIMIT:               equ 0af25h
DICTIONARY_POOL_BLOCK_SIZE:         equ 008h
DICTIONARY_FIRST_BLOCK_NAME_BYTES:  equ 004h
DICTIONARY_EXTRA_BLOCK_NAME_BYTES:  equ 008h

; Relation-database scratch.  ADDCL uses these words while it transforms a
; caller-owned clause term into the persistent compiled representation and
; splices the resulting node into the selected relation list.
DATABASE_NEW_CLAUSE_PAIR:             equ 09a85h
DATABASE_RELATION_VALUE_CELL:          equ 09a87h
ADDCL_APPEND_POSITION:                 equ 07fffh ; any larger request appends

; Fresh-variable map shared by the generic term copier and ADDCL compiler.
; Entries are source-variable addresses.  The high byte 0xFF in the next slot
; terminates the table; the entry ordinal multiplied by three is the relative
; local-environment offset stored in compiled clauses.
FRESH_VARIABLE_SOURCE_MAP:             equ 0986fh
FRESH_VARIABLE_MAP_END_HIGH:           equ FRESH_VARIABLE_SOURCE_MAP+1

; -----------------------------------------------------------------------------
; Central execution state and 12-byte continuation/choice records
; -----------------------------------------------------------------------------
; The interpreter keeps the hot execution registers in fixed workspace words.
; Selecting a user clause copies these six words, in order, into a 12-byte
; record after the clause's local-variable cells.  The record is both a return
; continuation and, when another clause remains, a backtracking choice point.
;
; The field names below are supported by allocation, normal return, cut, and
; rollback paths.  EXEC_ALLOCATION_TOP is the next free byte while the matching
; frame field records the base of the selected clause's local environment.
EXEC_FRAME_TOP:                 equ 0983dh
EXEC_ROOT_FRAME:                equ 0983fh
; ----------------------------------------------------------------------------
; THE SIX HOT WORDS
; ----------------------------------------------------------------------------
;
; These addresses are the micro-PROLOG equivalent of a processor register set.
; The inner interpreter keeps the current clause cursor, frame, goal stream,
; choice point, trail head and allocation frontier here because fixed-address
; loads are cheaper than repeatedly indexing a larger structure.
;
; Selecting a clause snapshots all six words into a frame.  Backtracking
; restores all six in one LDIR.  That symmetry is the central control-flow
; trick of the system: failure is not a collection of special cases, but a
; restoration of an earlier virtual-machine state.
;
; ----------------------------------------------------------------------------
; TRANSITIONS OF THE SIX HOT LOGICAL WORDS
; ----------------------------------------------------------------------------
;
;   event             fields which principally change
;   ----------------  -------------------------------------------------------
;   call entry         NEXT_CLAUSE and LOCAL_BASE describe the selected call;
;                      CALLER, caller GOALS, PREVIOUS_CHOICE and SAVED_TRAIL
;                      preserve the continuation in the new frame
;   goal success       CURRENT_GOALS advances to its tail; frame is unchanged
;   clause failure     all six words are restored from the newest choice frame
;                      and NEXT_CLAUSE becomes the retry relation-list suffix
;   normal return      caller frame and caller remaining goals are restored;
;                      execution/local frontier is rewound to the caller
;
; These words act like the registers of the Prolog virtual machine.  A frame is
; a frozen copy from which failure or return can reconstruct a prior state.
EXEC_NEXT_CLAUSE:                equ 09841h
EXEC_CURRENT_FRAME:              equ 09843h
EXEC_CURRENT_GOALS:              equ 09845h
EXEC_CHOICE_FRAME:               equ 09847h
EXEC_TRAIL_HEAD:                 equ 09849h
EXEC_ALLOCATION_TOP:             equ 0984bh

; Scratch values describing the clause currently being attempted.
EXEC_SELECTED_BODY:              equ 0984dh
EXEC_CALL_ARGUMENTS:             equ 0984fh
EXEC_SELECTED_HEAD:              equ 09851h
EXEC_CALLER_ENV_BASE:            equ 09853h
EXEC_CLAUSE_ENV_BASE:            equ 09855h
EXEC_PREVIOUS_FRAME_TOP:         equ 09857h
EXEC_RELOCATION_DELTA:           equ 09859h

; Managed-term allocation state.  Six-byte heap objects are allocated downward
; from TERM_HEAP_CURSOR.  FREE_TERM_OBJECT_HEAD links reusable two-cell objects;
; TERM_HEAP_COLLECTION_TRIGGER is the adaptive address that triggers collection
; before another downward allocation.  EXEC_ARENA_ORIGIN is the fixed high heap
; boundary used by collector address classification.
EXEC_ARENA_ORIGIN:                equ 09839h
TERM_HEAP_CURSOR:                 equ 0983bh
FREE_TERM_OBJECT_HEAD:            equ 0985bh
TERM_HEAP_COLLECTION_TRIGGER:     equ 0985dh
TERM_HEAP_FREE_BYTES:             equ 0985fh
TERM_HEAP_FREE_BYTES_HIGH:        equ TERM_HEAP_FREE_BYTES+1

; Every user-relation call receives a frame because every call needs a
; continuation.  A frame becomes a *choice point* only when the selected clause
; has a following clause: then EXEC_CHOICE_FRAME is made to point at that frame.
; A last-clause call still has a frame, but leaves the older choice point visible.
EXEC_FRAME_SIZE:                equ 00ch
; ----------------------------------------------------------------------------
; EXECUTION FRAMES: CONTINUATION AND CHOICE POINT IN ONE RECORD
; ----------------------------------------------------------------------------
;
; A selected user clause receives one twelve-byte frame.  The same record does
; two jobs.  It remembers where successful execution returns, and—when another
; clause remains—it remembers enough state to retry after failure.
;
; The six hot words at EXEC_NEXT_CLAUSE are copied into this layout when a frame
; is built and copied back when a choice point is restored.  This literal block
; copy is why the field order matters so much: it is an on-disk-style ABI inside
; the interpreter itself.
;
; Logical caller order and physical frame order are not identical.  Normal
; return follows EXEC_FRAME_CALLER.  Garbage collection walks physically
; allocated frames, including suspended choice points.  Tail-call relocation
; can change physical placement while preserving the logical links.
;
EXEC_FRAME_NEXT_CLAUSE:         equ 000h
EXEC_FRAME_CALLER:              equ 002h
EXEC_FRAME_CALLER_GOALS:        equ 004h
EXEC_FRAME_PREVIOUS_CHOICE:     equ 006h
EXEC_FRAME_SAVED_TRAIL:         equ 008h
EXEC_FRAME_LOCAL_BASE:          equ 00ah

